-- Terms can be set per grade: a grade with a row here uses its terms, any other the sheet's terms.
CREATE TABLE sheet_grade_terms (
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    CHAR(1)      NOT NULL,
    terms    INT          NOT NULL,
    PRIMARY KEY (sheet_id, grade)
);

-- A claim's due-by is fixed when it is added. Existing claims keep the due-by they show: their
-- date plus their sheet's terms.
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim SET due_by = DATEADD(DAY, (SELECT s.terms FROM sheet s WHERE s.id = claim.sheet_id), claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's figure bound by its person's last statement: stated is set on each claim that counted
-- when the statement was taken, with the due it had then (empty when it had none). The claim then
-- shows and totals that figure until the person's next statement rebinds or clears it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

-- Each statement taken for a person: their due-total at that moment (empty when it was n/a) and the
-- sheet's today when it was taken.
CREATE TABLE statement (
    id             BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id       VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id      BIGINT       NOT NULL REFERENCES person (id),
    due_total      DECIMAL(14, 2),
    statement_date DATE         NOT NULL,
    taken_by       VARCHAR(100) NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims in list order: newest first, a moved claim as the newest when it moved. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** The next place in the claims' list, after every claim added or moved so far. */
    @Query(value = "select next value for claim_listed_seq", nativeQuery = true)
    long nextListed();

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    /** The last place given in a period's numbering on the sheet (empty name: in no period); 0 if none. */
    @Query("select coalesce(max(c.numberSeq), 0) from Claim c where c.sheetId = :sheetId and c.numberPeriod = :period")
    int lastNumberWithin(String sheetId, String period);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Late, Session } from '../../core/session';
import { Period, closedOn, periodOn } from '../periods/periods';
import { NA, dueCents } from '../rates/rates';

/**
 * DRAFT when added, then OPEN, then SETTLED; a clerk's settling above the clerk limit makes it
 * PENDING until a steward approves it (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING
 * claim can be made VOID.
 */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A status change a claim's buttons ask for. */
type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject';

export interface Claim {
  id: number;
  personId: number;
  /** Always two decimals, e.g. "2.50". */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened and kept once VOID; null while DRAFT. */
  /** The sheet-wide number, or <period name>-<n> (X-<n> in no period) when numbered by period; null while DRAFT. */
  number: string | null;
  /** The due fixed when it was settled, two decimals; null while its due is live. */
  settledDue: string | null;
  /** The user who opened it; null while DRAFT. They cannot settle it. */
  openedBy: string | null;
  /** Bound by its person's last statement, to the due it had then; not while PENDING, when its due is live. */
  stated: boolean;
  /** The due bound by its person's last statement, two decimals; null while not stated, or stated with none. */
  statedDue: string | null;
  /** A correction's (negative amount's) number of the SETTLED claim it corrects; null for any other claim. */
  corrects: string | null;
  /** The date it is due by (yyyy-mm-dd), fixed when it was added; it does not move with its date or the terms. */
  dueBy: string;
}

/** A person's rate on a date: the rate then of the grade they had then, or null when it has none. */
export type PctOn = (date: string) => string | null;

/** Open: OPEN, or PENDING, which is handled like it. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Only open (OPEN or PENDING) and SETTLED claims count toward what is claimed and due. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** Whether its due is now bound by its person's last statement: stated and not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** Whether the claim counts for its person held or not: a held person's open claims do not. */
export function countsFor(c: Claim, held: boolean): boolean {
  return held ? c.status === 'SETTLED' : counts(c);
}

/** A claim's amount as cents, so sums are exact; a correction's is negative. */
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const size = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
